root=Path(sys.argv[1]).resolve()
ARTICLES=json.loads(r'''[{"slug":"bouquet-as-gift","image":"flowers-08.webp","langs":{"hy":["Ինչպես ընտրել ծաղկեփունջ նվերի համար Հայաստանում","Գույների, ծաղիկների ու առիթի ընտրության պարզ ուղեցույց՝ գեղեցիկ նվեր պատրաստելու համար։","Սկսեք առիթից, ոչ թե չափից","Ծաղկեփունջ ընտրելիս առաջին հարցը սովորաբար գինն է կամ ծաղիկների քանակը։ Բայց ամենահաջող նվերը սկսվում է մարդուց․ ինչ գույներ է սիրում, ինչպիսի տրամադրություն ունի և ինչ առիթով եք նրան շնորհավորում։ Նուրբ վարդագույն երանգները տաք ու հանգիստ են, վառ խառը փնջերը՝ տոնական, իսկ սպիտակ ծաղիկները՝ զուսպ ու էլեգանտ։","Եթե նախասիրությունները չգիտեք, ընտրեք երկու կամ երեք ներդաշնակ գույն ունեցող կոմպոզիցիա։ Շատ տարբեր տեսակներ համադրելու փոխարեն կարևոր է, որ փունջը միասնական տեսք ունենա։ Rose & Co-ի իրական աշխատանքների նկարները կարող են օգնել պատկերացնել համաչափությունն ու ոճը։","Ինչ հաշվի առնել մինչև պատվերը","Մտածեք՝ փունջը տանո՞ւմ եք անձամբ, թե՞ պետք է փոխանցվի ուրիշին։ Խոշոր կոմպոզիցիան տպավորիչ է, բայց երբեմն փոքրիկ, հարմար փունջն ավելի բնական է։ Եթե նվերը նախատեսված է աշխատավայրի կամ հիվանդասենյակի համար, ավելի խելամիտ է ընտրել կոմպակտ ծավալ ու չեզոք բույր։","Առաքման կամ հանդիպման ժամն էլ կարևոր է․ ծաղիկները լավագույնն են, երբ հանձնվում են ճիշտ պահին։ Նախապես փոխանցեք ստացողի մոտավոր նախասիրությունները, ցանկալի գույներն ու նախատեսված օրը։","Հարցրեք առկայությունն ու վերջնական կազմը","Սեզոնը ազդում է ընտրության վրա․ ամեն ծաղիկ տարվա բոլոր ամիսներին հավասարապես հասանելի չէ։ Լուսանկարը թող ծառայի որպես ոճի օրինակ, իսկ վերջնական տեսակներն ու քանակը ճշտեք ծաղկավաճառից։","Եթե ձեզ դուր է եկել կոնկրետ կոմպոզիցիա, ուղարկեք դրա լուսանկարը կամ անվանեք կատալոգի համարը։ Այդպես շատ ավելի հեշտ է պատրաստել ձեր ուզածին մոտ, բնական ու գեղեցիկ նվեր։"],"ru":["Как выбрать букет в подарок в Армении","Практичный гид по цветам, оттенкам и оформлению букета для близкого человека.","Начните с повода и вкусов человека","Выбор букета не обязательно начинается с количества роз. Гораздо полезнее вспомнить, какие цвета любит получатель, какой у него характер и по какому поводу вы готовите сюрприз. Пудровые оттенки смотрятся нежно, яркий микс подходит для праздника, а белая палитра создаёт спокойный элегантный образ.","Если предпочтения неизвестны, выбирайте композицию из двух-трёх гармоничных оттенков. Важнее цельная форма и баланс, чем большое число разных цветов. Реальные фотографии работ Rose & Co помогают увидеть подходящие варианты.","Что учесть до оформления заказа","Подумайте, где будут вручать цветы. Для офиса или небольшой комнаты удобен компактный букет; для торжественной встречи можно выбрать более выразительный. Сильный аромат не всегда уместен, поэтому лучше заранее уточнить состав.","Если букет будет передаваться через другого человека, сообщите желаемое время, оттенки и особенности упаковки. Эти детали влияют на впечатление не меньше размера композиции.","Уточните наличие и итоговый состав","Ассортимент цветов меняется в зависимости от сезона и поставок. Используйте фото как ориентир по стилю, а наличие конкретных сортов и окончательную цену уточняйте перед подтверждением заказа.","Сохраните понравившуюся фотографию или назовите номер товара в каталоге. Так флористу проще понять, какую форму, настроение и цветовую гамму вы хотите получить."],"en":["How to Choose a Bouquet as a Gift in Armenia","A practical guide to colors, flower styles and thoughtful gifting.","Start with the person and the occasion","A beautiful bouquet is not simply a matter of size. Think about the recipient's favorite colors, personality and the moment you want to celebrate. Blush pink feels gentle, vivid mixed flowers can feel joyful, and an ivory-and-white palette offers a calm, understated look.","When you are unsure of someone's preferences, a coherent arrangement in two or three complementary shades is often a safe starting point. Balance matters more than using as many different flowers as possible. Browse Rose & Co's real photographs for inspiration.","Consider how the bouquet will be received","A compact arrangement can be more practical in an office or a small apartment, while a special celebration may suit a more generous bouquet. Strong scents are not ideal in every setting, so ask about the varieties being used.","If someone else will deliver the gift, share the timing, approximate size and preferred wrapping style. These simple details can make the gesture feel much more personal.","Confirm availability before ordering","Flower availability varies through the year. Use a photograph to communicate the overall look, then confirm the exact varieties, quantity and final price with the florist.","If one arrangement catches your eye, send its photo or quote the catalog reference. It is the clearest way to explain the colors and shape you have in mind."]}},{"slug":"red-roses-51-101","image":"flowers-26.webp","langs":{"hy":["51 թե 101 կարմիր վարդ․ ինչպես ընտրել","Կարմիր վարդերի փնջերի տարբեր չափերը, առիթները և պատվերի կարևոր մանրամասները։","Վարդերի քանակը և կոմպոզիցիայի ազդեցությունը","51 կարմիր վարդից կազմված փունջն արդեն տպավորիչ նվեր է։ Այն հարմար է ծննդյան, տարեդարձի կամ սիրելի մարդու համար պատրաստված անակնկալի դեպքում։ 101 վարդից կազմված փունջը շատ ավելի խոշոր է և ինքնուրույն դառնում է տոնական պահի կենտրոնը։","Սակայն մեծությունը միշտ չէ, որ որոշիչ է։ Ծաղկի բացվածքը, ցողունների երկարությունը, փաթեթավորման ոճը և փնջի ձևը կարող են նույն քանակի վարդերին տարբեր տեսք տալ։","Ինչպես ստանալ ներդաշնակ արդյունք","Խիտ կլոր փունջը շքեղ ու հավաք տեսք ունի, իսկ ավելի ազատ դասավորությունը՝ բնական։ Եթե նախընտրում եք դասական նվեր, մուգ կարմիր վարդերն ու զուսպ փաթեթավորումը հարմար համադրություն են։","Խորհուրդ է տրվում հաշվի առնել նաև տեղափոխումը․ շատ մեծ փունջը պետք է հարմար լինի պահելու և տեղադրելու համար։ Նախապես ճշտեք՝ արդյոք ստացողը ծաղկաման ունի համապատասխան չափով։","Ինչ ճշտել Rose & Co-ից","Մինչև պատվերը հաստատելը հարցրեք տվյալ պահին վարդերի առկայությունը, գլխիկների մոտավոր չափը և վերջնական կոմպոզիցիան։ Գները կախված են սեզոնից, տեսակից և քանակից։","Մեր կատալոգում ներկայացված են իրական կարմիր վարդերի փնջերի նկարներ։ Ընտրեք ձեզ դուր եկած ոճը և կապ հաստատեք՝ վերջնական մանրամասները համաձայնեցնելու համար։"],"ru":["51 или 101 красная роза: как выбрать букет","Размер, оформление и практические нюансы заказа большого букета роз.","В чём разница между 51 и 101 розой","Букет из 51 красной розы уже выглядит торжественно. Он подходит для дня рождения, годовщины или романтического сюрприза. Композиция из 101 розы заметно объёмнее и часто становится главным акцентом праздника.","При этом число цветков — не единственный критерий. Размер бутонов, длина стеблей, плотность сборки и упаковка существенно меняют итоговый вид даже при одинаковом количестве роз.","Форма и упаковка","Плотный округлый букет выглядит классически и нарядно. Более свободная сборка создаёт естественное настроение. Для красных роз хорошо подходит сдержанная упаковка, которая не отвлекает внимание от самих цветов.","Большую композицию важно удобно перевезти и затем поставить в вазу. Перед заказом подумайте о месте вручения и о том, как цветы будут размещены после праздника.","Что спросить у флориста","Уточните наличие, оттенок и приблизительный размер бутонов, возможную длину стеблей и окончательную стоимость. Эти параметры меняются с сезоном и поставками.","В каталоге Rose & Co можно посмотреть реальные фотографии красных роз и подобрать понравившуюся подачу. Согласуйте детали перед оформлением заказа."],"en":["51 or 101 Red Roses: Choosing the Right Bouquet","Understand the differences in scale, presentation and practical ordering details.","How the number of roses changes the impression","A bouquet of 51 red roses already makes a strong statement for a birthday, anniversary or thoughtful romantic occasion. An arrangement of 101 roses is much larger and can become the visual centerpiece of the celebration.","The quantity is not the only factor. Rose head size, stem length, arrangement density and wrapping can make bouquets with the same number of stems feel very different.","Shape, styling and practicality","A dense round bouquet looks classic and formal. A looser arrangement can feel more natural. With red roses, understated wrapping often lets the rich color remain the focus.","Consider transport and where the recipient will place the flowers. A very large bouquet may need a suitably large vase or more than one container.","Confirm the details before ordering","Ask about current availability, shade, approximate bloom size and the finished arrangement. Final prices vary according to the season, variety and number of stems.","Rose & Co's catalog includes photographs of real rose arrangements. Choose the style you like, then contact the florist to confirm the details."]}},{"slug":"flower-baskets","image":"flowers-39.webp","langs":{"hy":["Ծաղիկներ զամբյուղում․ երբ ընտրել նման նվեր","Զամբյուղով ծաղկային կոմպոզիցիաների առավելությունները, խնամքն ու ոճային տարբերակները։","Զամբյուղի հարմարավետությունը","Ծաղկային զամբյուղը հարմար նվեր է այն դեպքում, երբ ցանկանում եք, որ կոմպոզիցիան փոխանցվի արդեն պատրաստ տեսքով։ Այն կարելի է դնել սեղանին կամ հյուրասենյակի տեսանելի հատվածում՝ առանց հավելյալ ծաղկամանի որոնման։","Նման ձևավորումը գեղեցիկ է տարեդարձերի, շնորհավորանքների և ընտանեկան հանդիպումների ժամանակ։ Նուրբ պաստելային ծաղիկները ստեղծում են հանգիստ տրամադրություն, իսկ վառ երանգները՝ ավելի աշխույժ տպավորություն։","Ինչպիսի ծաղիկներ ընտրել","Վարդերը, քրիզանթեմները և այլ սեզոնային ծաղիկները կարելի է ներդաշնակ համադրել մեկ զամբյուղում։ Կարևոր է, որ բարձրությունն ու ծավալը համապատասխանեն զամբյուղի ձևին և չծանրացնեն ընդհանուր տեսքը։","Եթե կոմպոզիցիան նախատեսված է գրասեղանի համար, ընտրեք ավելի ցածր տարբերակ։ Մեծ սրահում կամ հատուկ արարողության ժամանակ կարող եք նախընտրել ավելի ընդգծված ծավալ։","Ինչպես խնամել զամբյուղի ծաղիկները","Որոշ զամբյուղներում ծաղիկները տեղադրվում են խոնավություն պահող ֆլորիստիկական հիմքի մեջ։ Խնամքի ձևը կախված է հենց օգտագործված կառուցվածքից, ուստի ծաղկավաճառից ճշտեք՝ ինչպես և որքան հաճախ խոնավացնել։","Խուսափեք ուժեղ արևից, տաքացուցիչներից և ջրի ավելցուկից։ Պատվիրելիս նշեք նախատեսված վայրը, որպեսզի Rose & Co-ն օգնի ընտրել համապատասխան ձևն ու չափը։"],"ru":["Цветы в корзине: когда выбрать такую композицию","Преимущества цветочных корзин, идеи для подарка и особенности ухода.","Почему корзина — удобный формат","Цветочная корзина — готовая композиция, которую можно поставить на стол или в гостиную без поиска подходящей вазы. Это практично, когда подарок нужно красиво вручить и сразу разместить.","Корзины уместны на днях рождения, семейных праздниках и при поздравлениях. Нежные оттенки создают спокойное настроение, а насыщенные цвета делают оформление более заметным.","Какие цветы подходят","Розы, хризантемы и другие сезонные цветы можно сочетать в одном оформлении. Важно, чтобы высота и объём соответствовали форме корзины. Излишне пышная композиция не всегда выглядит лучше сбалансированной.","Для рабочего стола подойдёт более низкая корзина, а для просторного помещения можно выбрать крупный вариант. Расскажите флористу, где будет стоять подарок.","Уход за цветочной корзиной","Иногда стебли закрепляют во флористической основе, удерживающей влагу. Способ увлажнения зависит от материала, поэтому уточняйте правила ухода при получении готовой композиции.","Защищайте цветы от прямого солнца и тепла, не заливайте основу водой без рекомендации. В Rose & Co можно подобрать корзину по оттенкам, размеру и настроению."],"en":["Flowers in Baskets: A Thoughtful Gift Idea","When a basket arrangement works best and how to care for it.","A ready-to-display arrangement","A flower basket is a complete arrangement that can be placed on a table or shelf without searching for a vase. It is a practical gift when the recipient may want to enjoy the flowers immediately.","Basket arrangements suit birthdays, family gatherings and personal congratulations. Soft colors feel gentle, while richer shades make the arrangement more expressive.","Choose a balanced composition","Roses, chrysanthemums and other seasonal flowers can be combined in a basket. The height of each variety should suit the basket's proportions. A well-balanced shape often looks more refined than an overly crowded arrangement.","For a desk, choose a lower design; for a larger room, a fuller arrangement may work well. Mention the intended location when discussing your order.","How to care for basket flowers","Some floral baskets use a moisture-retaining base. The correct watering routine depends on the specific materials, so ask the florist how to keep the arrangement hydrated.","Keep flowers away from direct heat and harsh sunlight, and avoid adding excess water. Rose & Co can help you select colors and proportions to suit the occasion."]}},{"slug":"sunflower-bouquets","image":"flowers-41.webp","langs":{"hy":["Արևածաղիկների փունջ․ արևոտ նվեր ցանկացած առիթի","Արևածաղիկներով կոմպոզիցիաների գույները, համադրությունները և խնամքը։","Ինչու են արևածաղիկները առանձնանում","Արևածաղիկը նույնիսկ փոքր փնջին տալիս է ուրախ ու տաք տրամադրություն։ Նրա խոշոր դեղին թերթիկները և արտահայտիչ կենտրոնը գեղեցիկ են և՛ առանձին, և՛ այլ ծաղիկների հետ։ Այդ պատճառով արևածաղիկների փունջը հաճախ ընտրում են ծննդյան, շնորհավորանքի կամ պարզապես լավ օր մաղթելու համար։","Դեղինի կողքին կանաչ տերևները ստեղծում են բնական հակադրություն։ Եթե ուզում եք ավելի մեղմ կոմպոզիցիա, կարելի է համադրել բաց կրեմագույն կամ սպիտակ ծաղիկների հետ։","Ինչ ձևավորում ընտրել","Երկար ցողուններով արևածաղիկները լավ են նայվում ազատ, փոքր-ինչ ասիմետրիկ փնջերում։ Ավելորդ դեկորը կարող է ծածկել ծաղիկների բնավորությունը, ուստի պարզ թուղթը կամ ժապավենը հաճախ բավարար է։","Ավելի հավաք տեսքի համար ընտրեք միանման բարձրության ծաղիկներ, իսկ բնական ոճի դեպքում թողեք մի քանի ցողուն ավելի բարձր։ Լուսանկարում պատկերված ծաղիկների քանակն ու տեսքը կարելի է օգտագործել որպես քննարկման օրինակ։","Արևածաղիկների խնամքի պարզ քայլերը","Ցողունները կտրեք մաքուր գործիքով, հեռացրեք ջրի տակ հայտնվող տերևները և ծաղկամանը պահեք զով հատվածում։ Ջուրը փոխեք պարբերաբար, իսկ ծաղիկները հեռու պահեք ուղիղ արևից և ջեռուցման աղբյուրներից։","Առկայությունը կարող է սեզոնային լինել։ Rose & Co-ից նախապես ճշտեք արևածաղիկների և ցանկալի համադրության հնարավոր տարբերակները։"],"ru":["Букет подсолнухов: солнечный подарок на любой повод","Сочетания оттенков, идеи оформления и простой уход за подсолнухами.","Чем привлекательны подсолнухи","Даже небольшой букет подсолнухов выглядит радостно и тепло. Их выразительные жёлтые лепестки и крупная серединка хороши сами по себе и в сочетании с другими растениями. Такой букет выбирают для дня рождения, поздравления или просто чтобы поднять настроение.","Зелень создаёт естественный контраст с жёлтым цветом. Для более мягкой палитры можно добавить кремовые или белые цветы.","Как красиво оформить букет","Подсолнухи хорошо смотрятся в свободных, слегка асимметричных букетах. Чрезмерный декор может отвлекать от их естественной формы, поэтому спокойная упаковка и небольшая лента часто лучше пышных украшений.","Для аккуратного вида выбирают стебли близкой высоты; для более природного настроения можно оставить некоторые цветки выше других.","Как сохранить свежесть","Подрежьте стебли чистым инструментом, уберите листья ниже уровня воды и поставьте букет в прохладном месте. Меняйте воду регулярно, избегайте прямого солнца и близости отопительных приборов.","Доступность подсолнухов может зависеть от сезона. До заказа уточните в Rose & Co наличие и возможные сочетания."],"en":["Sunflower Bouquets: A Bright and Happy Gift","How to style sunflower arrangements and keep them looking fresh.","Why sunflowers stand out","Even a simple sunflower bouquet feels warm and cheerful. Its golden petals and bold center create a striking shape, whether the flowers are arranged alone or with other seasonal blooms. It is a thoughtful choice for birthdays and congratulations.","Greenery balances the yellow naturally. White or pale cream flowers can soften the overall look if you prefer a quieter palette.","Styling a sunflower bouquet","Sunflowers work well in loose, slightly asymmetrical arrangements. Too much decoration can compete with their strong character, so natural paper and a simple ribbon are often enough.","For a neat look, select flowers of similar heights; for a more organic shape, let a few stems sit taller than the rest. Use reference photos to discuss the desired proportions.","Keeping sunflowers fresh","Trim stems with a clean tool, remove any leaves that would sit in water and place the bouquet in a cool location. Replace the water regularly and keep it away from direct sun and radiators.","Sunflower availability can vary with the season. Contact Rose & Co to confirm which combinations can be prepared."]}},{"slug":"white-flower-arrangements","image":"flowers-31.webp","langs":{"hy":["Սպիտակ ծաղիկների կոմպոզիցիաներ․ նրբագեղ ու հանգիստ ընտրություն","Սպիտակ և կրեմագույն ծաղիկների համադրությունների գաղափարներ տարբեր առիթների համար։","Սպիտակի նուրբ արտահայտչականությունը","Սպիտակ ծաղիկները կարող են արտահայտել պարզություն, հարգանք կամ հանգիստ գեղեցկություն՝ կախված առիթից և ձևավորումից։ Դրանք հաճախ ընտրում են հարսանեկան արարողությունների, շնորհավորանքների և զուսպ ինտերիերի համար։","Սպիտակի տարբեր երանգները միատեսակ չեն․ կաթնագույն, փղոսկրագույն և մաքուր սպիտակ ծաղիկները միասին տալիս են ծավալ ու խորություն, հատկապես երբ ավելացվում է մեղմ կանաչ։","Ինչպես համադրել տարբեր ծաղիկները","Սպիտակ վարդերը, քրիզանթեմները և սեզոնային մանր ծաղիկները կարելի է օգտագործել տարբեր չափի կոմպոզիցիաներում։ Կարևոր է տեսնել յուրաքանչյուր ծաղկի ձևն ու կառուցվածքը, որպեսզի ամբողջը չդառնա միատարր։","Նվերի համար սերտ հավաքված փունջը ավելի դասական է, իսկ զամբյուղը կամ ազատ դասավորված կոմպոզիցիան՝ ավելի բնական։ Ցանկալի ոճը կախված է ստացողից և այն վայրից, որտեղ ծաղիկները պետք է դրվեն։","Երբ ընտրել սպիտակ կոմպոզիցիա","Սպիտակը հարմար է, երբ ուզում եք խուսափել չափազանց վառ երանգներից։ Միևնույն ժամանակ առիթի բնույթը կարևոր է․ հարսանեկան ու հիշատակի ձևավորումները կարող են օգտագործել նման գույներ, բայց տարբեր ձևեր ու տրամադրություն։","Կատալոգի լուսանկարով Rose & Co-ին փոխանցեք ձեր նախընտրած ձևը, իսկ առկայությունն ու վերջնական կազմը ճշտեք նախապես։"],"ru":["Белые цветочные композиции: спокойная элегантность","Как сочетать белые и кремовые цветы для разных поводов.","Почему белая палитра так универсальна","Белые цветы создают ощущение простоты, уважения и спокойной красоты — значение зависит от события и оформления. Их часто выбирают для свадеб, поздравлений и интерьеров, где не хочется слишком ярких оттенков.","Оттенки белого различаются. Молочные, кремовые и чисто-белые цветки вместе с мягкой зеленью добавляют композиции глубину и объём.","Сочетание видов и фактур","Белые розы, хризантемы и небольшие сезонные цветы можно соединить в одном букете. Главное — учитывать форму каждого бутона, чтобы композиция выглядела естественно и не теряла деталей.","Плотно собранный букет более классический, а корзина или свободная сборка создают непринуждённое впечатление. Выбор зависит от получателя и места, где будут стоять цветы.","Для каких случаев подходит белый","Белая гамма уместна, когда нужен сдержанный подарок. Но для свадебного оформления и памятной церемонии одинаковые цвета могут потребовать совсем разной формы и настроения.","Покажите флористу Rose & Co понравившуюся фотографию и уточните наличие подходящих цветов и окончательный состав."],"en":["White Flower Arrangements: Quiet Elegance","A guide to styling white and ivory flowers for different occasions.","The beauty of a restrained palette","White flowers can express simplicity, respect or understated beauty, depending on the occasion. They are often chosen for weddings, thoughtful gifts and interiors that benefit from a calm palette.","White is not a single shade. Ivory, cream and pure-white blooms can add depth when arranged together with soft green foliage.","Mixing flowers and textures","White roses, chrysanthemums and smaller seasonal flowers can share one arrangement. Consider the different shapes and textures so the composition does not look flat or overly uniform.","A closely arranged bouquet feels classic; a basket or more open composition can feel natural. Let the setting and the recipient guide the design.","When to choose white flowers","Choose a pale palette when you want a subtle result rather than a bold splash of color. The same colors can appear in both celebratory and memorial designs, yet require very different shapes and presentation.","Share a reference photograph with Rose & Co and confirm current availability and the finished composition before ordering."]}},{"slug":"ordering-flowers-guide","image":"editorial-03.webp","langs":{"hy":["Ինչպես պատվիրել ծաղկեփունջ․ 5 կարևոր մանրուք","Պատվերից առաջ ինչ ասել ծաղկավաճառին, որպեսզի արդյունքը համապատասխանի սպասումներին։","Նկարագրեք առիթը և ցանկալի տեսքը","Ծաղկեփունջ պատվիրելիս պարտադիր չէ իմանալ ծաղիկների բոլոր անունները։ Բավական է ասել՝ ինչ առիթի համար է նվերը, ինչ գույներ եք սիրում և որքան մեծ պետք է լինի կոմպոզիցիան։ Եթե ունեք ձեր նախընտրած լուսանկարը, ուղարկեք այն։","Լուսանկարը օգնում է հասկանալ ընդհանուր ոճը, սակայն վերջնական փունջը կարող է փոքր-ինչ տարբերվել՝ կախված սեզոնային ծաղիկների առկայությունից։ Այդ պատճառով կարևոր է նախապես քննարկել ոչ միայն գույնը, այլև մոտավոր ձևը և փաթեթավորումը։","Հստակեցրեք գործնական հարցերը","Նշեք ցանկալի ամսաթիվը, ժամը և փոխանցման ձևը։ Եթե պատվերը պետք է հասնի կոնկրետ վայր, համոզվեք, որ հասցեն և ստացողի հետ կապի պայմանները հստակ են։ Եթե ծաղկեփունջը անձամբ եք վերցնելու, ճշտեք պատրաստ լինելու պահը։","Նախընտրելի է նաև ասել՝ արդյոք կան ծաղիկներ կամ ուժեղ բույրեր, որոնցից պետք է խուսափել։ Նման փոքր մանրամասներն օգնում են փունջը դարձնել ավելի անձնական։","Գինը, ծաղիկների քանակը և վերջնական հաստատումը","Քանի որ տարբեր ծաղիկների գները և առկայությունը փոխվում են, վերջնական արժեքն ավելի ճիշտ է ճշտել ընտրված կազմով։ Պատվերի հաստատումից առաջ համաձայնեցրեք քանակը, գունապնակը, փաթեթավորումը և վճարման պայմանները։","Rose & Co-ի կատալոգում կարող եք ընտրել իրական աշխատանքներից մեկը և նշել դրա համարը։ Զանգահարեք կամ գրեք 033 081 898 համարով, որպեսզի միասին որոշենք հնարավոր տարբերակը։"],"ru":["Как заказать букет: пять важных деталей","Что сообщить флористу до заказа, чтобы результат соответствовал ожиданиям.","Опишите повод и желаемый стиль","Чтобы заказать букет, не обязательно знать названия всех цветов. Расскажите, для кого он предназначен, какие оттенки нравятся и насколько объёмной должна быть композиция. Если есть понравившаяся фотография, отправьте её.","Фото помогает понять настроение, но точный состав может изменяться в зависимости от сезонного наличия. Поэтому лучше обсудить форму, основные цвета и упаковку, а не только повторение картинки.","Согласуйте практические вопросы","Укажите желаемые дату, время и способ получения. Если нужно передать букет в конкретное место, заранее уточните адрес и возможность связаться с получателем. При самовывозе важно знать время готовности.","Также скажите, есть ли цветы или интенсивные ароматы, которых стоит избегать. Эти небольшие уточнения делают подарок более личным.","Цена и окончательное подтверждение","Стоимость зависит от состава, количества и доступности цветов. Перед подтверждением согласуйте оттенки, упаковку, размер и условия оплаты, чтобы не возникло недопонимания.","В каталоге Rose & Co можно выбрать реальную работу и назвать её номер. Свяжитесь с нами по телефону 033 081 898, чтобы уточнить возможный вариант."],"en":["How to Order a Flower Bouquet: Five Useful Details","What to share with your florist before placing an order.","Describe the occasion and style","You do not need to know every flower by name to order a bouquet. Tell the florist whom the gift is for, which colors you prefer and how large you would like the arrangement to be. A reference photo can be especially helpful.","A photo communicates the general mood, although the final flowers may vary depending on seasonal availability. Discuss the shape and wrapping as well as the color palette.","Agree on practical details","Share the requested date, time and preferred handover method. If the bouquet needs to reach a particular location, confirm the address and any necessary recipient details. If you will collect it yourself, ask when it can be ready.","Mention any flowers or strong fragrances you would prefer to avoid. These details can make the finished gift more thoughtful.","Confirm the composition and price","The final price depends on the varieties, quantity and availability of flowers. Before confirming an order, agree on the general arrangement, colors, wrapping and payment terms.","You can select a real arrangement from Rose & Co's catalog and quote its reference number. Call or message 033 081 898 to discuss what can be prepared."]}}]''')
langs=('hy','ru','en')
srcprefix='/rose-and-co/assets/images/real-2026/'
root_url='https://alform-creator.github.io/rose-and-co/'
copy={
'hy':{'back':'← Վերադառնալ բլոգ','read':'Կարդալ հոդվածը ↗','tag':'ԾԱՂԻԿՆԵՐ • ԽՈՐՀՈՒՐԴՆԵՐ','cta':'Դիտել ծաղկեփնջերի կատալոգը ↗','intro':'Իրական ծաղկային աշխատանքներ, գործնական խորհուրդներ և գաղափարներ՝ Rose & Co-ից։','more':'Տեսնել բոլոր հոդվածները ↗'},
'ru':{'back':'← Вернуться в блог','read':'Читать статью ↗','tag':'ЦВЕТЫ • СОВЕТЫ','cta':'Посмотреть каталог букетов ↗','intro':'Реальные композиции, полезные советы и идеи от Rose & Co.','more':'Читать все статьи ↗'},
'en':{'back':'← Back to journal','read':'Read story ↗','tag':'FLOWERS • JOURNAL','cta':'Explore the flower catalog ↗','intro':'Real floral work, practical advice and inspiration from Rose & Co.','more':'Read all stories ↗'}
}
today='2026-10-25'
for lang in langs:
    journal=root/lang/'journal'/'index.html'
    soup=BeautifulSoup(journal.read_text(encoding='utf-8'),'html.parser')
    grid=soup.select_one('.journal-grid')
    if not grid:raise RuntimeError('Journal grid missing: '+str(journal))
    if len(grid.select('.journal-card'))!=4:raise RuntimeError('Expected 4 original articles')
    template=(root/lang/'journal'/'flower-care'/'index.html').read_text(encoding='utf-8')
    for i,entry in enumerate(ARTICLES,5):
        title,summary,h2a,p1,p2,h3,p3,p4,h2b,p5,p6=entry['langs'][lang]
        image=srcprefix+entry['image']+'?v=journal20261025'
        slug=entry['slug']
        url=f'/rose-and-co/{lang}/journal/{slug}/'
        assert '..' not in slug
        card_markup=(f'<a class="journal-card" href="{url}">'
          f'<div class="journal-photo"><img src="{image}" loading="lazy" decoding="async" width="820" height="950" alt="{escape(title,quote=True)}"/><span class="journal-index">{i:02d}</span></div>'
          f'<span class="eyebrow">ROSE &amp; CO JOURNAL</span>'
          f'<h3>{escape(title)}</h3><p>{escape(summary)}</p>'
          f'<span class="journal-read">{copy[lang]["read"]}</span></a>')
        grid.append(BeautifulSoup(card_markup,'html.parser').a)
        page=BeautifulSoup(template,'html.parser')
        # Replace the source article's main content while keeping shared navigation,
        # language switcher, footer, contact actions, original brand and animations.
        main=page.select_one('main')
        if not main:raise RuntimeError('Article template missing main')
        inner=(f'<section class="article-hero container">'
            f'<a class="article-back" href="/rose-and-co/{lang}/journal/">{copy[lang]["back"]}</a>'
            f'<span class="eyebrow">ROSE &amp; CO · THE JOURNAL</span>'
            f'<h1>{escape(title)}</h1><p>{escape(summary)}</p>'
            f'<div class="article-photo"><img src="{image}" alt="{escape(title,quote=True)}" width="820" height="950" loading="eager" decoding="async"/></div></section>'
            f'<article class="container article-body">'
            f'<h2 class="seo-article-h2">{escape(h2a)}</h2><p>{escape(p1)}</p><p>{escape(p2)}</p>'
            f'<h3 class="seo-article-h3">{escape(h3)}</h3><p>{escape(p3)}</p><p>{escape(p4)}</p>'
            f'<h2 class="seo-article-h2">{escape(h2b)}</h2><p>{escape(p5)}</p><p>{escape(p6)}</p>'
            f'<div class="journal-article-cta"><span class="eyebrow">ROSE &amp; CO</span>'
            f'<p>{escape(copy[lang]["intro"])}</p>'
            f'<a class="button btn-burgundy" href="/rose-and-co/{lang}/catalog/">{copy[lang]["cta"]}</a></div>'
            f'</article><div class="container article-return"><a class="button btn-outline" href="/rose-and-co/{lang}/journal/">{copy[lang]["back"]}</a></div>')
        main.clear()
        for node in list(BeautifulSoup(inner,'html.parser').contents):
            main.append(node)
        page.title.string=f'{title} | Rose & Co'
        for selector,value in [('meta[name="description"]',summary),
                               ('meta[property="og:description"]',summary),
                               ('meta[property="og:title"]',title+' — Rose & Co'),
                               ('meta[property="og:image"]',image)]:
            meta=page.select_one(selector)
            if meta:meta['content']=value
        for alternate in page.select('link[rel="alternate"]'):
            hl=alternate.get('hreflang')
            if hl in langs:alternate['href']=f'/rose-and-co/{hl}/journal/{slug}/'
            if hl=='x-default':alternate['href']=f'/rose-and-co/hy/journal/{slug}/'
        canonical=page.select_one('link[rel="canonical"]')
        if canonical:
            canonical['href']=root_url+lang+'/journal/'+slug+'/'
        else:
            head=page.head
            node=page.new_tag('link',rel='canonical',href=root_url+lang+'/journal/'+slug+'/')
            head.append(node)
        # Meaningful photograph alt and Article structured data for the new page.
        ld=page.new_tag('script',type='application/ld+json')
        ld.string=json.dumps({
            '@context':'https://schema.org','@type':'BlogPosting',
            'headline':title,'description':summary,
            'image':root_url+'assets/images/real-2026/'+entry['image'],
            'datePublished':today,'dateModified':today,
            'inLanguage':lang,
            'mainEntityOfPage':root_url+lang+'/journal/'+slug+'/',
            'publisher':{'@type':'Organization','name':'Rose & Co'}
        },ensure_ascii=False)
        page.head.append(ld)
        # Brand logo and refined fonts have already been added by earlier steps.
        # Keep browser cache versions consistent in generated locale pages.
        folder=root/lang/'journal'/slug
        folder.mkdir(parents=True,exist_ok=True)
        (folder/'index.html').write_text(str(page),encoding='utf-8')
    # Replace previous non-wreath memorial blog preview with a real customer's wreath.
    memorial=grid.select_one('.journal-card[href*="/memorial-wreaths/"] img')
    if not memorial:raise RuntimeError('Missing memorial article card')
    memorial['src']=srcprefix+'wreaths-05.webp?v=memorial20261025'
    memorial['alt']={'hy':'Իրական կարմիր ու սպիտակ ծաղկեպսակ Rose & Co-ից',
                     'ru':'Настоящий красно-белый траурный венок Rose & Co',
                     'en':'Real red-and-white memorial wreath by Rose & Co'}[lang]
    journal.write_text(str(soup),encoding='utf-8')
    # The existing wreath article should use a user-supplied wreath photo too.
    memorial_path=root/lang/'journal'/'memorial-wreaths'/'index.html'
    article=BeautifulSoup(memorial_path.read_text(encoding='utf-8'),'html.parser')
    image_node=article.select_one('.article-photo img')
    if not image_node:raise RuntimeError('Missing memorial article photo')
    image_node['src']=srcprefix+'wreaths-05.webp?v=memorial20261025'
    image_node['alt']=memorial['alt']
    image_node['loading']='eager'
    og=article.select_one('meta[property="og:image"]')
    if og:og['content']=root_url+'assets/images/real-2026/wreaths-05.webp'
    memorial_path.write_text(str(article),encoding='utf-8')

# Sitemap rebuild: original archive used malformed repo-base URLs. Replace with
# actual existing, canonical local page paths; include 6x3 new posts.
from xml.etree.ElementTree import Element, SubElement, ElementTree
urls=[]
for lang in langs:
    for p in sorted((root/lang).rglob('index.html')):
        urls.append(root_url+p.parent.relative_to(root).as_posix()+'/')
urls.append(root_url)
urlset=Element('urlset',{'xmlns':'http://www.sitemaps.org/schemas/sitemap/0.9'})
for url in sorted(set(urls)):
    node=SubElement(urlset,'url')
    SubElement(node,'loc').text=url
ElementTree(urlset).write(root/'sitemap.xml',encoding='utf-8',xml_declaration=True)
print(f'Rose & Co: added 6 new articles per language, 18 pages, + real wreath photos, {len(urls)} sitemap entries')
